 1→package jlsm.table.internal;
 2→
 3→import jlsm.table.JlsmDocument;
 4→import jlsm.table.JlsmSchema;
 5→
 6→/**
 7→ * Friend-accessor bridge that grants {@code jlsm.table.internal} code access to package-private
 8→ * members of {@link JlsmDocument}.
 9→ *
10→ * <p>
11→ * {@link JlsmDocument} registers an implementation of {@link Accessor} via
12→ * {@link #setAccessor(Accessor)} during its static initialiser. Internal classes retrieve the
13→ * accessor via {@link #get()} and use it to call package-private operations.
14→ *
15→ * <p>
16→ * This pattern avoids widening the visibility of package-private members in the public API while
17→ * still allowing the {@code jlsm.table.internal} package to operate on document internals.
18→ */
19→public final class DocumentAccess {
20→
21→    /** Provides access to package-private members of {@link JlsmDocument}. */
22→    public interface Accessor {
23→
24→        /**
25→         * Returns the raw values array of the document (in schema-field order).
26→         *
27→         * @param doc the document; must not be null
28→         * @return the internal values array
29→         */
30→        Object[] values(JlsmDocument doc);
31→
32→        /**
33→         * Constructs a {@link JlsmDocument} directly from a schema and pre-built values array.
34→         *
35→         * @param schema the schema; must not be null
36→         * @param values the values in schema-field order; must not be null
37→         * @return a new JlsmDocument
38→         */
39→        JlsmDocument create(JlsmSchema schema, Object[] values);
40→    }
41→
42→    private static volatile Accessor accessor;
43→
44→    private DocumentAccess() {
45→    }
46→
47→    /**
48→     * Registers the accessor implementation. Must be called exactly once by {@link JlsmDocument}'s
49→     * static initialiser before any other use.
50→     *
51→     * @param a the accessor; must not be null
52→     * @throws IllegalStateException if called more than once
53→     */
54→    public static void setAccessor(Accessor a) {
55→        if (a == null) {
56→            throw new IllegalArgumentException("accessor must not be null");
57→        }
58→        if (accessor != null) {
59→            throw new IllegalStateException("DocumentAccess.accessor already set");
60→        }
61→        accessor = a;
62→    }
63→
64→    /**
65→     * Returns the registered accessor.
66→     *
67→     * @return the accessor; never null after class initialisation completes
68→     * @throws IllegalStateException if the accessor has not been registered yet
69→     */
70→    public static Accessor get() {
71→        final Accessor a = accessor;
72→        if (a == null) {
73→            // Force JlsmDocument to load so it registers the accessor
74→            try {
75→                Class.forName("jlsm.table.JlsmDocument");
76→            } catch (ClassNotFoundException e) {
77→                throw new IllegalStateException("JlsmDocument class not found", e);
78→            }
79→        }
80→        final Accessor loaded = accessor;
81→        if (loaded == null) {
82→            throw new IllegalStateException(
83→                    "DocumentAccess.accessor not initialised; JlsmDocument static init may have failed");
84→        }
85→        return loaded;
86→    }
87→}
