  1→package jlsm.table;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jlsm.encryption.EncryptionKeyHolder;
  5→import jlsm.table.internal.FieldEncryptionDispatch;
  6→import jdk.incubator.vector.ByteVector;
  7→import jdk.incubator.vector.DoubleVector;
  8→import jdk.incubator.vector.FloatVector;
  9→import jdk.incubator.vector.IntVector;
 10→import jdk.incubator.vector.LongVector;
 11→import jdk.incubator.vector.VectorShuffle;
 12→import jdk.incubator.vector.VectorSpecies;
 13→
 14→import java.lang.foreign.MemorySegment;
 15→import java.lang.foreign.ValueLayout;
 16→import java.nio.charset.StandardCharsets;
 17→import java.util.List;
 18→import java.util.Objects;
 19→import java.util.Optional;
 20→
 21→/**
 22→ * Binary serializer for {@link JlsmDocument} values.
 23→ *
 24→ * <p>
 25→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 26→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 27→ *
 28→ * <p>
 29→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 30→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 31→ * {@code null}.
 32→ *
 33→ * <p>
 34→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 35→ * {@code jdk.incubator.vector}.
 36→ */
 37→public final class DocumentSerializer {
 38→
 39→    private DocumentSerializer() {
 40→    }
 41→
 42→    /**
 43→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 44→     * schema.
 45→     *
 46→     * @param schema the schema describing the document structure; must not be null
 47→     * @return a MemorySerializer for JlsmDocument
 48→     */
 49→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 50→        Objects.requireNonNull(schema, "schema must not be null");
 51→        return new SchemaSerializer(schema, /* keyHolder= */ null);
 52→    }
 53→
 54→    /**
 55→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 56→     * schema, with optional field-level encryption.
 57→     *
 58→     * @param schema the schema describing the document structure; must not be null
 59→     * @param keyHolder the key holder for encryption; may be null (no encryption)
 60→     * @return a MemorySerializer for JlsmDocument
 61→     */
 62→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema,
 63→            EncryptionKeyHolder keyHolder) {
 64→        Objects.requireNonNull(schema, "schema must not be null");
 65→        return new SchemaSerializer(schema, keyHolder);
 66→    }
 67→
 68→    // =========================================================================
 69→    // Implementation
 70→    // =========================================================================
 71→
 72→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 73→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 74→
 75→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 76→    private static final VectorShuffle<Byte> BSWAP32;
 77→
 78→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 79→    private static final VectorShuffle<Byte> BSWAP64;
 80→
 81→    static {
 82→        final int byteLen = BYTE_SPECIES.length();
 83→        final int[] idx32 = new int[byteLen];
 84→        final int[] idx64 = new int[byteLen];
 85→        for (int i = 0; i + 3 < byteLen; i += 4) {
 86→            idx32[i + 0] = i + 3;
 87→            idx32[i + 1] = i + 2;
 88→            idx32[i + 2] = i + 1;
 89→            idx32[i + 3] = i + 0;
 90→        }
 91→        for (int i = 0; i + 7 < byteLen; i += 8) {
 92→            idx64[i + 0] = i + 7;
 93→            idx64[i + 1] = i + 6;
 94→            idx64[i + 2] = i + 5;
 95→            idx64[i + 3] = i + 4;
 96→            idx64[i + 4] = i + 3;
 97→            idx64[i + 5] = i + 2;
 98→            idx64[i + 6] = i + 1;
 99→            idx64[i + 7] = i + 0;
100→        }
101→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
102→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
103→    }
104→
105→    // -------------------------------------------------------------------------
106→    // Serializer implementation
107→    // -------------------------------------------------------------------------
108→
109→    /** Decodes a single non-boolean, non-null field from a byte array at the cursor position. */
110→    @FunctionalInterface
111→    private interface FieldDecoder {
112→        Object decode(byte[] buf, Cursor cursor);
113→    }
114→
115→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
116→
117→        private final JlsmSchema schema;
118→        private final boolean[] isBoolField;
119→        private final int[] prefixBoolCount;
120→        private final int fieldCount;
121→        private final int boolCount;
122→        private final int nullMaskBytes;
123→        private final int boolMaskBytes;
124→        private final FieldDecoder[] decoders;
125→        private final FieldEncryptionDispatch encryptionDispatch;
126→
127→        SchemaSerializer(JlsmSchema schema, EncryptionKeyHolder keyHolder) {
128→            this.schema = schema;
129→
130→            final List<FieldDefinition> fields = schema.fields();
131→            this.fieldCount = fields.size();
132→            final FieldDefinition[] fieldArray = fields.toArray(new FieldDefinition[0]);
133→
134→            // Precompute boolean field flags and prefix counts
135→            this.isBoolField = new boolean[fieldCount];
136→            this.prefixBoolCount = new int[fieldCount + 1];
137→            int bools = 0;
138→            for (int i = 0; i < fieldCount; i++) {
139→                prefixBoolCount[i] = bools;
140→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
141→                    isBoolField[i] = true;
142→                    bools++;
143→                }
144→            }
145→            prefixBoolCount[fieldCount] = bools;
146→            this.boolCount = bools;
147→
148→            this.nullMaskBytes = (fieldCount + 7) / 8;
149→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
150→

150→
151→            // Build dispatch table for non-boolean field decoders
152→            this.decoders = new FieldDecoder[fieldCount];
153→            for (int i = 0; i < fieldCount; i++) {
154→                if (!isBoolField[i]) {
155→                    final FieldType type = fieldArray[i].type();
156→                    decoders[i] = (buf, cursor) -> decodeField(buf, cursor, type);
157→                }
158→            }
159→
160→            // Build encryption dispatch (null-safe: null keyHolder means no encryption)
161→            this.encryptionDispatch = new FieldEncryptionDispatch(schema, keyHolder);
162→        }
163→
164→        @Override
165→        public MemorySegment serialize(JlsmDocument doc) {
166→            Objects.requireNonNull(doc, "doc must not be null");
167→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
168→                    : "document schema mismatch";
169→
170→            final List<FieldDefinition> fields = schema.fields();
171→            final int fieldCount = fields.size();
172→            final Object[] values = doc.values();
173→
174→            // Count boolean fields
175→            final int boolCount = countBoolFields(fields);
176→
177→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
178→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
179→            final int nullMaskBytes = (fieldCount + 7) / 8;
180→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
181→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
182→
183→            // Pre-encrypt fields that have encryptors to determine actual payload size.
184→            // encryptedPayloads[i] holds the ciphertext for encrypted fields, null otherwise.
185→            final byte[][] encryptedPayloads = new byte[fieldCount][];
186→            boolean hasEncryptedFields = false;
187→            for (int i = 0; i < fieldCount; i++) {
188→                final Object val = values[i];
189→                if (val == null || isBoolField[i]) {
190→                    continue;
191→                }
192→                final FieldEncryptionDispatch.FieldEncryptor enc = encryptionDispatch
193→                        .encryptorFor(i);
194→                if (enc != null) {
195→                    // Serialize the field value to a temporary buffer, then encrypt
196→                    final byte[] plainBytes = serializeFieldToBytes(fields.get(i).type(), val);
197→                    encryptedPayloads[i] = enc.encrypt(plainBytes);
198→                    hasEncryptedFields = true;
199→                }
200→            }
201→
202→            // Two-pass: measure then encode
203→            final int payloadSize;
204→            if (!hasEncryptedFields) {
205→                payloadSize = measureFields(fields, values);
206→            } else {
207→                payloadSize = measureFieldsWithEncryption(fields, values, encryptedPayloads);
208→            }
209→            final int totalSize = headerSize + payloadSize;
210→
211→            final byte[] buf = new byte[totalSize];
212→
213→            // Write header
214→            writeShortBE(buf, 0, (short) schema.version());
215→            writeShortBE(buf, 2, (short) fieldCount);
216→            // Null bitmask
217→            buildNullMask(fields, values, buf, 4);
218→            // Boolean bitmask
219→            if (boolCount > 0) {
220→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
221→            }
222→
223→            // Write values
224→            final Cursor cursor = new Cursor(buf, headerSize);
225→            if (!hasEncryptedFields) {
226→                encodeFields(fields, values, cursor);
227→            } else {
228→                encodeFieldsWithEncryption(fields, values, encryptedPayloads, cursor);
229→            }
230→
231→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
232→            return MemorySegment.ofArray(buf);
233→        }
234→
235→        @Override
236→        public JlsmDocument deserialize(MemorySegment segment) {
237→            Objects.requireNonNull(segment, "segment must not be null");
238→
239→            final ByteArrayView view = extractBytes(segment);
240→            final byte[] buf = view.data();
241→            final Cursor cursor = new Cursor(buf, view.offset());
242→
243→            // Read header
244→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
245→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
246→
247→            // We only read min(writeFieldCount, currentFieldCount) fields
248→            final int readCount = Math.min(writeFieldCount, fieldCount);
249→
250→            // Use precomputed prefixBoolCount for O(1) lookup instead of O(n) iteration
251→            final int writeBoolCount = prefixBoolCount[readCount];
252→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
253→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
254→
255→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
256→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
257→
258→            // Decode values
259→            final Object[] values = new Object[fieldCount];
260→            // Fields beyond readCount remain null (new fields added in a later schema version)
261→
262→            int boolIdx = 0;
263→            for (int i = 0; i < readCount; i++) {
264→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
265→                if (isNull) {
266→                    if (isBoolField[i]) {
267→                        boolIdx++;
268→                    }
269→                    continue;
270→                }
271→                if (isBoolField[i]) {
272→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
273→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
274→                    boolIdx++;
275→                } else {
276→                    final FieldEncryptionDispatch.FieldDecryptor dec = encryptionDispatch
277→                            .decryptorFor(i);
278→                    if (dec != null) {
279→                        // Read length-prefixed encrypted blob, decrypt, then decode
280→                        final int encLen = readVarInt(buf, cursor);
281→                        final byte[] ciphertext = new byte[encLen];
282→                        System.arraycopy(buf, cursor.pos, ciphertext, 0, encLen);
283→                        cursor.pos += encLen;
284→                        final byte[] plainBytes = dec.decrypt(ciphertext);
285→                        final Cursor plainCursor = new Cursor(plainBytes, 0);
286→                        values[i] = decoders[i].decode(plainBytes, plainCursor);
287→                    } else {
288→                        values[i] = decoders[i].decode(buf, cursor);
289→                    }
290→                }
291→            }
292→
293→            return new JlsmDocument(schema, values);
294→        }
295→    }
