297→    // =========================================================================
298→    // Measure helpers (first pass)
299→    // =========================================================================
300→
301→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
302→        int total = 0;
303→        for (int i = 0; i < fields.size(); i++) {
304→            final FieldDefinition fd = fields.get(i);
305→            final Object val = values[i];
306→            if (val == null) {
307→                continue; // null → no value bytes
308→            }
309→            total += measureField(fd.type(), val);
310→        }
311→        return total;
312→    }
313→
314→    private static int measureField(FieldType type, Object value) {
315→        return switch (type) {
316→            case FieldType.Primitive p -> switch (p) {
317→                case STRING -> {
318→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
319→                    yield varIntSize(utf8.length) + utf8.length;
320→                }
321→                case INT8 -> 1;
322→                case INT16 -> 2;
323→                case INT32 -> 4;
324→                case INT64 -> 8;
325→                case FLOAT16 -> 2;
326→                case FLOAT32 -> 4;
327→                case FLOAT64 -> 8;
328→                case BOOLEAN -> 0; // packed in bitmask
329→                case TIMESTAMP -> 8;
330→            };
331→            case FieldType.ArrayType at -> {
332→                final Object[] arr = (Object[]) value;
333→                int sz = varIntSize(arr.length);
334→                for (Object elem : arr) {
335→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
336→                }
337→                yield sz;
338→            }
339→            case FieldType.VectorType vt -> {
340→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
341→                yield vt.dimensions() * elemBytes;
342→            }
343→            case FieldType.ObjectType ot -> {
344→                final JlsmDocument sub = (JlsmDocument) value;
345→                final List<FieldDefinition> subFields = ot.fields();
346→                final int subBoolCount = countBoolFields(subFields);
347→                final int subNullBytes = (subFields.size() + 7) / 8;
348→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
349→                int sz = subNullBytes + subBoolBytes;

