 15→/**
 16→ * Dispatch table mapping field positions to their encryption/decryption functions. Constructed once
 17→ * at serializer creation time; immutable and thread-safe after construction.
 18→ *
 19→ * <p>
 20→ * For each field in the schema, checks its {@link EncryptionSpec} and builds the appropriate
 21→ * encryptor/decryptor pair. If the key holder is {@code null}, all entries are {@code null} (no
 22→ * encryption).
 23→ *
 24→ * <p>
 25→ * Governed by: .decisions/field-encryption-api-design/adr.md
 26→ */
 27→public final class FieldEncryptionDispatch {
 28→
 29→    private final FieldEncryptor[] encryptors;
 30→    private final FieldDecryptor[] decryptors;
 31→
 32→    /**
 33→     * Encrypts a byte array field value.
 34→     */
 35→    @FunctionalInterface
 36→    public interface FieldEncryptor {
 37→        byte[] encrypt(byte[] plaintext);
 38→    }
 39→
 40→    /**
 41→     * Decrypts a byte array field value.
 42→     */
 43→    @FunctionalInterface
 44→    public interface FieldDecryptor {
 45→        byte[] decrypt(byte[] ciphertext);
 46→    }
 47→
 48→    /**
 49→     * Constructs a dispatch table for the given schema and key holder.
 50→     *
 51→     * @param schema the schema describing the document structure; must not be null
 52→     * @param keyHolder the key holder providing encryption keys; may be null (no encryption)
 53→     */
 54→    public FieldEncryptionDispatch(JlsmSchema schema, EncryptionKeyHolder keyHolder) {
 55→        assert schema != null : "schema must not be null";
 56→
 57→        final List<FieldDefinition> fields = schema.fields();
 58→        final int fieldCount = fields.size();
 59→        this.encryptors = new FieldEncryptor[fieldCount];
 60→        this.decryptors = new FieldDecryptor[fieldCount];
 61→
 62→        if (keyHolder == null) {
 63→            // No encryption — all entries remain null
 64→            return;
 65→        }
 66→
 67→        for (int i = 0; i < fieldCount; i++) {
 68→            final FieldDefinition fd = fields.get(i);
 69→            final EncryptionSpec spec = fd.encryption();
 70→
 71→            switch (spec) {
 72→                case EncryptionSpec.None _ -> {
 73→                    // No encryption for this field
 74→                }
 75→                case EncryptionSpec.Deterministic _ -> {
 76→                    // AES-SIV requires a 64-byte key. If the table key is 32 bytes,
 77→                    // derive a 64-byte key by repeating it.
 78→                    final EncryptionKeyHolder sivKeyHolder;
 79→                    if (keyHolder.keyLength() == 32) {
 80→                        final byte[] halfKey = keyHolder.getKeyBytes();
 81→                        final byte[] sivKey = new byte[64];
 82→                        System.arraycopy(halfKey, 0, sivKey, 0, 32);
 83→                        System.arraycopy(halfKey, 0, sivKey, 32, 32);
 84→                        Arrays.fill(halfKey, (byte) 0);
 85→                        sivKeyHolder = EncryptionKeyHolder.of(sivKey);
 86→                    } else {
 87→                        sivKeyHolder = keyHolder;
 88→                    }
 89→                    final AesSivEncryptor siv = new AesSivEncryptor(sivKeyHolder);
 90→                    final byte[] associatedData = fd.name().getBytes(StandardCharsets.UTF_8);
 91→                    encryptors[i] = plaintext -> siv.encrypt(plaintext, associatedData);
 92→                    decryptors[i] = ciphertext -> siv.decrypt(ciphertext, associatedData);
 93→                }
 94→                case EncryptionSpec.OrderPreserving _ -> {
 95→                    // OrderPreserving requires domain/range configuration.
 96→                    // For generic byte-level dispatch, use long-based OPE.
 97→                    final BoldyrevaOpeEncryptor ope = new BoldyrevaOpeEncryptor(keyHolder,
 98→                            Long.MAX_VALUE / 2, Long.MAX_VALUE);
 99→                    encryptors[i] = plaintext -> opeEncryptBytes(ope, plaintext);
100→                    decryptors[i] = ciphertext -> opeDecryptBytes(ope, ciphertext);
101→                }
102→                case EncryptionSpec.DistancePreserving _ -> {
103→                    // DistancePreserving operates on float[] vectors, not byte[].
104→                    // Handled separately in the serializer. Leave null for byte dispatch.
105→                }
106→                case EncryptionSpec.Opaque _ -> {
107→                    // AES-GCM requires a 32-byte key. If the table key is 64 bytes,
108→                    // derive a 32-byte sub-key from the first half.
109→                    final EncryptionKeyHolder gcmKeyHolder;
110→                    if (keyHolder.keyLength() == 64) {
111→                        final byte[] fullKey = keyHolder.getKeyBytes();
112→                        final byte[] gcmKey = Arrays.copyOfRange(fullKey, 0, 32);
113→                        Arrays.fill(fullKey, (byte) 0);
114→                        gcmKeyHolder = EncryptionKeyHolder.of(gcmKey);
115→                    } else {
116→                        gcmKeyHolder = keyHolder;
117→                    }
118→                    final AesGcmEncryptor gcm = new AesGcmEncryptor(gcmKeyHolder);
119→                    encryptors[i] = gcm::encrypt;
120→                    decryptors[i] = gcm::decrypt;
121→                }
122→            }
123→        }
124→    }
125→
126→    /**
127→     * Returns the encryptor for the field at the given index, or {@code null} if no encryption is
128→     * configured.
129→     *
130→     * @param fieldIndex the zero-based field index
131→     * @return the encryptor, or null
132→     */
133→    public FieldEncryptor encryptorFor(int fieldIndex) {
134→        assert fieldIndex >= 0 && fieldIndex < encryptors.length
135→                : "fieldIndex out of bounds: " + fieldIndex;
136→        return encryptors[fieldIndex];
137→    }
138→
139→    /**
140→     * Returns the decryptor for the field at the given index, or {@code null} if no encryption is
141→     * configured.
142→     *
143→     * @param fieldIndex the zero-based field index
144→     * @return the decryptor, or null
145→     */
146→    public FieldDecryptor decryptorFor(int fieldIndex) {
147→        assert fieldIndex >= 0 && fieldIndex < decryptors.length
148→                : "fieldIndex out of bounds: " + fieldIndex;
149→        return decryptors[fieldIndex];
150→    }
151→
152→    // -- OPE byte helpers -------------------------------------------------
153→
154→    /**
155→     * Encodes a byte[] as a positive long, encrypts with OPE, returns the encrypted long as bytes.
156→     */
157→    private static byte[] opeEncryptBytes(BoldyrevaOpeEncryptor ope, byte[] plaintext) {
158→        final long value = bytesToPositiveLong(plaintext);
159→        final long encrypted = ope.encrypt(value);
160→        return longToBytes(encrypted);
161→    }
162→
163→    /**
164→     * Decrypts OPE ciphertext bytes back to the original byte[] representation.
165→     */
166→    private static byte[] opeDecryptBytes(BoldyrevaOpeEncryptor ope, byte[] ciphertext) {
167→        final long encValue = bytesTo8ByteLong(ciphertext);
168→        final long decrypted = ope.decrypt(encValue);
169→        return positiveLongToBytes(decrypted);
170→    }
171→
172→    /**
173→     * Converts up to 6 bytes of data into a positive long in [1..Long.MAX_VALUE/2]. Format: first
174→     * byte = original length, followed by up to 6 data bytes packed into a long.
175→     */
176→    private static long bytesToPositiveLong(byte[] data) {
177→        assert data != null : "data must not be null";
178→        if (data.length > 6) {
179→            throw new IllegalArgumentException(
180→                    "OPE byte encryption supports at most 6 bytes of data, got " + data.length);
181→        }
182→        long result = 1; // ensure positive, minimum = 1
183→        result += ((long) data.length) << 48;
184→        for (int i = 0; i < data.length; i++) {
185→            result += ((long) (data[i] & 0xFF)) << (40 - i * 8);
186→        }
187→        return result;
188→    }
189→
190→    private static byte[] positiveLongToBytes(long value) {
191→        value -= 1; // undo the +1 offset
192→        final int len = (int) ((value >>> 48) & 0xFF);
193→        final byte[] result = new byte[len];
194→        for (int i = 0; i < len; i++) {
195→            result[i] = (byte) ((value >>> (40 - i * 8)) & 0xFF);
196→        }
197→        return result;
198→    }
199→
200→    private static byte[] longToBytes(long value) {
201→        final byte[] buf = new byte[8];
202→        for (int i = 0; i < 8; i++) {
203→            buf[i] = (byte) (value >>> (56 - i * 8));
204→        }
205→        return buf;
206→    }
207→
208→    private static long bytesTo8ByteLong(byte[] buf) {
209→        assert buf.length == 8 : "expected 8 bytes for long";
210→        long result = 0;
211→        for (int i = 0; i < 8; i++) {
212→            result |= ((long) (buf[i] & 0xFF)) << (56 - i * 8);
213→        }
214→        return result;
215→    }
216→}
