  1→package jlsm.table;
  2→
  3→import java.util.List;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * Represents the type of a field in a {@link JlsmSchema}.
  8→ *
  9→ * <p>
 10→ * FieldType is a sealed interface with three permitted implementations:
 11→ * <ul>
 12→ * <li>{@link Primitive} — an enum of scalar types</li>
 13→ * <li>{@link ArrayType} — a homogeneous array of a given element type</li>
 14→ * <li>{@link ObjectType} — a nested object with its own field definitions</li>
 15→ * </ul>
 16→ */
 17→public sealed interface FieldType permits FieldType.Primitive, FieldType.ArrayType,
 18→        FieldType.ObjectType, FieldType.VectorType {
 19→
 20→    /** Scalar primitive field types. */
 21→    enum Primitive implements FieldType {
 22→        STRING, INT8, INT16, INT32, INT64, FLOAT16, FLOAT32, FLOAT64, BOOLEAN, TIMESTAMP
 23→    }
 24→
 25→    /**
 26→     * A homogeneous array of elements, all sharing the same {@link FieldType}.
 27→     *
 28→     * @param elementType the type of each element in the array; must not be null
 29→     */
 30→    record ArrayType(FieldType elementType) implements FieldType {
 31→        public ArrayType {
 32→            Objects.requireNonNull(elementType, "elementType must not be null");
 33→        }
 34→    }
 35→
 36→    /**
 37→     * A nested object type with an ordered list of named fields.
 38→     *
 39→     * @param fields the field definitions of the nested object; must not be null
 40→     */
 41→    record ObjectType(List<FieldDefinition> fields) implements FieldType {
 42→        public ObjectType {
 43→            Objects.requireNonNull(fields, "fields must not be null");
 44→            fields = List.copyOf(fields);
 45→        }
 46→
 47→        /**
 48→         * Creates a {@link JlsmSchema} from this ObjectType's field definitions.
 49→         *
 50→         * @param name the schema name; must not be null
 51→         * @param version the schema version
 52→         * @return a new JlsmSchema with this ObjectType's fields
 53→         */
 54→        public JlsmSchema toSchema(String name, int version) {
 55→            Objects.requireNonNull(name, "name must not be null");
 56→            JlsmSchema.Builder builder = JlsmSchema.builder(name, version);
 57→            for (FieldDefinition fd : fields) {
 58→                builder.field(fd.name(), fd.type());
 59→            }
 60→            return builder.build();
 61→        }
 62→    }
 63→
 64→    /**
 65→     * A fixed-dimension vector of floating-point elements.
 66→     *
 67→     * @param elementType the element precision; must be {@link Primitive#FLOAT16} or
 68→     *            {@link Primitive#FLOAT32}
 69→     * @param dimensions the fixed number of elements per vector; must be positive
 70→     */
 71→    record VectorType(Primitive elementType, int dimensions) implements FieldType {
 72→        public VectorType {
 73→            Objects.requireNonNull(elementType, "elementType must not be null");
 74→            if (elementType != Primitive.FLOAT16 && elementType != Primitive.FLOAT32) {
 75→                throw new IllegalArgumentException(
 76→                        "VectorType elementType must be FLOAT16 or FLOAT32, got: " + elementType);
 77→            }
 78→            if (dimensions <= 0) {
 79→                throw new IllegalArgumentException(
 80→                        "VectorType dimensions must be positive, got: " + dimensions);
 81→            }
 82→        }
 83→    }
 84→
 85→    // --- Static factory shortcuts ---
 86→
 87→    /** Returns {@link Primitive#STRING}. */
 88→    static FieldType string() {
 89→        return Primitive.STRING;
 90→    }
 91→
 92→    /** Returns {@link Primitive#INT32}. */
 93→    static FieldType int32() {
 94→        return Primitive.INT32;
 95→    }
 96→
 97→    /** Returns {@link Primitive#INT64}. */
 98→    static FieldType int64() {
 99→        return Primitive.INT64;
100→    }
101→
102→    /** Returns {@link Primitive#FLOAT32}. */
103→    static FieldType float32() {
104→        return Primitive.FLOAT32;
105→    }
106→
107→    /** Returns {@link Primitive#FLOAT64}. */
108→    static FieldType float64() {
109→        return Primitive.FLOAT64;
110→    }
111→
112→    /** Returns {@link Primitive#BOOLEAN}. */
113→    static FieldType boolean_() {
114→        return Primitive.BOOLEAN;
115→    }
116→
117→    /** Returns {@link Primitive#TIMESTAMP}. */
118→    static FieldType timestamp() {
119→        return Primitive.TIMESTAMP;
120→    }
121→
122→    /**
123→     * Returns a {@link VectorType} with the given element type and dimensions.
124→     *
125→     * @param elementType the element precision; must be FLOAT16 or FLOAT32
126→     * @param dimensions the fixed number of elements per vector; must be positive
127→     * @return a new VectorType
128→     */
129→    static FieldType vector(Primitive elementType, int dimensions) {
130→        return new VectorType(elementType, dimensions);
131→    }
132→
133→    /**
134→     * Returns an {@link ArrayType} with the given element type.
135→     *
136→     * @param elementType the element type; must not be null
137→     * @return a new ArrayType
138→     */
139→    static FieldType arrayOf(FieldType elementType) {
140→        assert elementType != null : "elementType must not be null";
141→        return new ArrayType(elementType);
142→    }
143→
144→    /**
145→     * Returns an {@link ObjectType} with the given field definitions.
146→     *
147→     * @param fields the field definitions; must not be null
148→     * @return a new ObjectType
149→     */
150→    static FieldType objectOf(List<FieldDefinition> fields) {
151→        assert fields != null : "fields must not be null";
152→        return new ObjectType(fields);
153→    }
154→}
