  3→import static org.junit.jupiter.api.Assertions.*;
  4→
  5→import java.lang.foreign.Arena;
  6→import java.lang.foreign.MemorySegment;
  7→import java.lang.foreign.ValueLayout;
  8→import java.util.Arrays;
