 10→import jlsm.core.io.MemorySerializer;
 11→import jlsm.encryption.EncryptionKeyHolder;
 12→import jlsm.encryption.EncryptionSpec;
 13→import org.junit.jupiter.api.AfterEach;
 14→import org.junit.jupiter.api.BeforeEach;
 15→import org.junit.jupiter.api.Test;
 16→
 17→class DocumentSerializerEncryptionTest {
 18→
 19→    private EncryptionKeyHolder keyHolder64;
 20→    private EncryptionKeyHolder keyHolder32;
 21→
 22→    @BeforeEach
 23→    void setUp() {
 24→        byte[] key64 = new byte[64];
 25→        Arrays.fill(key64, (byte) 0xAB);
 26→        keyHolder64 = EncryptionKeyHolder.of(key64);
 27→
 28→        byte[] key32 = new byte[32];
 29→        Arrays.fill(key32, (byte) 0xCD);
 30→        keyHolder32 = EncryptionKeyHolder.of(key32);
 31→    }
 32→
 33→    @AfterEach
 34→    void tearDown() {
 35→        if (keyHolder64 != null) {
 36→            keyHolder64.close();
 37→        }
 38→        if (keyHolder32 != null) {
 39→            keyHolder32.close();
 40→        }
 41→    }
 42→
 43→    // ── Round-trip with deterministic encrypted fields ───────────────────
 44→
 45→    @Test
 46→    void roundTrip_deterministicEncryptedString() {
 47→        JlsmSchema schema = JlsmSchema.builder("test", 1)
 48→                .field("name", FieldType.string(), EncryptionSpec.deterministic())
 49→                .field("age", FieldType.int32()).build();
 50→
 51→        JlsmDocument doc = JlsmDocument.of(schema, "name", "Alice", "age", 30);
 52→
 53→        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
 54→        MemorySegment bytes = ser.serialize(doc);
 55→        JlsmDocument out = ser.deserialize(bytes);
 56→
 57→        assertEquals("Alice", out.getString("name"));
 58→        assertEquals(30, out.getInt("age"));
 59→    }
 60→
 61→    // ── Round-trip with opaque encrypted fields ─────────────────────────
 62→
 63→    @Test
 64→    void roundTrip_opaqueEncryptedString() {
 65→        JlsmSchema schema = JlsmSchema.builder("test", 1)
 66→                .field("secret", FieldType.string(), EncryptionSpec.opaque())
 67→                .field("public_field", FieldType.string()).build();
 68→
 69→        JlsmDocument doc = JlsmDocument.of(schema, "secret", "top-secret", "public_field",
 70→                "visible");
 71→
 72→        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder32);
 73→        MemorySegment bytes = ser.serialize(doc);
 74→        JlsmDocument out = ser.deserialize(bytes);
 75→
 76→        assertEquals("top-secret", out.getString("secret"));
 77→        assertEquals("visible", out.getString("public_field"));
 78→    }
 79→
 80→    // ── Mixed schema: some encrypted, some not ──────────────────────────
 81→
 82→    @Test
 83→    void roundTrip_mixedEncryptedAndPlainFields() {
 84→        JlsmSchema schema = JlsmSchema.builder("test", 1)
 85→                .field("name", FieldType.string(), EncryptionSpec.deterministic())
 86→                .field("age", FieldType.int32()).field("email", FieldType.string())
 87→                .field("score", FieldType.float64()).build();
 88→
 89→        JlsmDocument doc = JlsmDocument.of(schema, "name", "Bob", "age", 25, "email",
 90→                "user@example.com", "score", 98.5);
 91→
 92→        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
 93→        MemorySegment bytes = ser.serialize(doc);
 94→        JlsmDocument out = ser.deserialize(bytes);
 95→
 96→        assertEquals("Bob", out.getString("name"));
 97→        assertEquals(25, out.getInt("age"));
 98→        assertEquals("user@example.com", out.getString("email"));
 99→        assertEquals(98.5, out.getDouble("score"), 0.001);
100→    }
101→
102→    // ── Deterministic encrypted field produces same ciphertext ──────────
103→
104→    @Test
105→    void deterministicEncryption_sameCiphertextForSameValue() {
106→        JlsmSchema schema = JlsmSchema.builder("test", 1)
107→                .field("name", FieldType.string(), EncryptionSpec.deterministic()).build();
108→
109→        JlsmDocument doc1 = JlsmDocument.of(schema, "name", "Alice");
110→        JlsmDocument doc2 = JlsmDocument.of(schema, "name", "Alice");
111→
112→        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
113→        MemorySegment bytes1 = ser.serialize(doc1);
114→        MemorySegment bytes2 = ser.serialize(doc2);
115→
116→        byte[] b1 = bytes1.toArray(ValueLayout.JAVA_BYTE);
117→        byte[] b2 = bytes2.toArray(ValueLayout.JAVA_BYTE);
118→        assertArrayEquals(b1, b2,
119→                "Deterministic encryption should produce identical serialized bytes for same value");
120→    }
121→
122→    // ── Unencrypted serialization unchanged (backward compat) ───────────
123→
124→    @Test
125→    void noEncryption_backwardCompatible() {
126→        JlsmSchema schema = JlsmSchema.builder("test", 1).field("name", FieldType.string())
127→                .field("age", FieldType.int32()).build();
128→
129→        JlsmDocument doc = JlsmDocument.of(schema, "name", "Charlie", "age", 40);
130→
131→        // Serializer without encryption
132→        MemorySerializer<JlsmDocument> serPlain = DocumentSerializer.forSchema(schema);
133→        // Serializer with null key (no encryption)
134→        MemorySerializer<JlsmDocument> serNull = DocumentSerializer.forSchema(schema, null);
135→
136→        MemorySegment bytesPlain = serPlain.serialize(doc);
137→        MemorySegment bytesNull = serNull.serialize(doc);
138→
139→        byte[] b1 = bytesPlain.toArray(ValueLayout.JAVA_BYTE);
140→        byte[] b2 = bytesNull.toArray(ValueLayout.JAVA_BYTE);
141→        assertArrayEquals(b1, b2,
142→                "Serialization with null keyHolder should match unencrypted serialization");
143→
144→        // Both should deserialize correctly
145→        JlsmDocument out1 = serPlain.deserialize(bytesPlain);
146→        JlsmDocument out2 = serNull.deserialize(bytesNull);
147→        assertEquals("Charlie", out1.getString("name"));
148→        assertEquals("Charlie", out2.getString("name"));
149→    }
150→
151→    // ── Off-heap segment deserialization with encrypted fields ───────────
152→
