370→    /**
371→     * Measures payload size when some fields are pre-encrypted. Encrypted fields are stored as
372→     * varint-length-prefixed blobs; unencrypted fields use standard measurement.
373→     */
374→    private static int measureFieldsWithEncryption(List<FieldDefinition> fields, Object[] values,
375→            byte[][] encryptedPayloads) {
376→        int total = 0;
377→        for (int i = 0; i < fields.size(); i++) {
378→            final Object val = values[i];
379→            if (val == null) {
380→                continue; // null → no value bytes
381→            }
382→            if (encryptedPayloads[i] != null) {
383→                // Length-prefixed encrypted blob
384→                total += varIntSize(encryptedPayloads[i].length) + encryptedPayloads[i].length;
385→            } else {
386→                total += measureField(fields.get(i).type(), val);
387→            }
388→        }
