393→     * Encodes fields with encryption support. Encrypted fields are written as
394→     * varint-length-prefixed blobs from the pre-encrypted payloads; unencrypted fields use the
395→     * standard encode path.
396→     */
397→    private static void encodeFieldsWithEncryption(List<FieldDefinition> fields, Object[] values,
398→            byte[][] encryptedPayloads, Cursor c) {
399→        for (int i = 0; i < fields.size(); i++) {
400→            final Object val = values[i];
