418→     * that will be fed to the field encryptor.
419→     */
420→    private static byte[] serializeFieldToBytes(FieldType type, Object value) {
421→        assert value != null : "value must not be null for serialization";
422→        final int size = measureField(type, value);
423→        final byte[] buf = new byte[size];
424→        final Cursor c = new Cursor(buf, 0);
425→        encodeField(c, type, value);
426→        assert c.pos == size : "encoded size mismatch: expected " + size + ", got " + c.pos;
427→        return buf;
428→    }
