430→    private static void encodeField(Cursor c, FieldType type, Object value) {
431→        switch (type) {
432→            case FieldType.Primitive p -> {
433→                switch (p) {
434→                    case STRING -> {
435→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
436→                        writeVarInt(c, utf8.length);
437→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
438→                        c.pos += utf8.length;
439→                    }
440→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
441→                    case INT16 -> {
442→                        writeShortBE(c.buf, c.pos, (Short) value);
443→                        c.pos += 2;
444→                    }
445→                    case INT32 -> {
446→                        writeIntBE(c.buf, c.pos, (Integer) value);
447→                        c.pos += 4;
448→                    }
449→                    case INT64 -> {
450→                        writeLongBE(c.buf, c.pos, (Long) value);
451→                        c.pos += 8;
452→                    }
453→                    case FLOAT16 -> {
454→                        writeShortBE(c.buf, c.pos, (Short) value);
455→                        c.pos += 2;
456→                    }
457→                    case FLOAT32 -> {
458→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
459→                        c.pos += 4;
460→                    }
461→                    case FLOAT64 -> {
462→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
463→                        c.pos += 8;
464→                    }
465→                    case BOOLEAN -> {
466→                        // Boolean values are packed in the bool bitmask; nothing here
467→                    }
468→                    case TIMESTAMP -> {
469→                        writeLongBE(c.buf, c.pos, (Long) value);
470→                        c.pos += 8;
471→                    }
472→                }
473→            }
474→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
475→            case FieldType.VectorType vt -> encodeVector(c, vt, value);
476→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
477→        }
478→    }
479→
480→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
481→        writeVarInt(c, arr.length);
482→        // SIMD-accelerated paths for contiguous numeric types
483→        if (elemType == FieldType.Primitive.INT32) {
484→            encodeInt32Array(c, arr);
485→        } else if (elemType == FieldType.Primitive.INT64) {
486→            encodeInt64Array(c, arr);
487→        } else if (elemType == FieldType.Primitive.FLOAT32) {
488→            encodeFloat32Array(c, arr);
489→        } else if (elemType == FieldType.Primitive.FLOAT64) {
490→            encodeFloat64Array(c, arr);
491→        } else {
492→            for (Object elem : arr) {
493→                if (elem != null) {
494→                    encodeField(c, elemType, elem);
495→                }
496→            }
497→        }
498→    }
499→
500→    private static void encodeVector(Cursor c, FieldType.VectorType vt, Object value) {
501→        final int d = vt.dimensions();
502→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
503→            final float[] vec = (float[]) value;
504→            assert vec.length == d : "vector length must match dimensions";
505→            for (int i = 0; i < d; i++) {
506→                writeIntBE(c.buf, c.pos, Float.floatToRawIntBits(vec[i]));
507→                c.pos += 4;
508→            }
509→        } else {
510→            // FLOAT16 — stored as short[]
511→            final short[] vec = (short[]) value;
512→            assert vec.length == d : "vector length must match dimensions";
513→            for (int i = 0; i < d; i++) {
514→                writeShortBE(c.buf, c.pos, vec[i]);
515→                c.pos += 2;
516→            }
517→        }
518→    }
519→
520→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
521→        final List<FieldDefinition> subFields = ot.fields();
522→        final Object[] subValues = sub.values();
523→        final int boolCount = countBoolFields(subFields);
524→        final int nullMaskBytes = (subFields.size() + 7) / 8;
525→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
526→
527→        final int nullMaskStart = c.pos;
528→        c.pos += nullMaskBytes;
529→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
530→        if (boolCount > 0) {
531→            c.pos += boolMaskBytes;
532→        }
533→
534→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
535→        if (boolCount > 0) {
536→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
537→        }
538→        encodeFields(subFields, subValues, c);
539→    }

