package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import jlsm.encryption.EncryptionSpec;
import jlsm.table.internal.CiphertextValidator;
import org.junit.jupiter.api.Test;

class CiphertextValidatorTest {

    // ── AES-SIV (Deterministic): accept >= 16 bytes ────────────────────────

    @Test
    void deterministic_accepts16Bytes() {
        FieldDefinition field = new FieldDefinition("email", FieldType.string(),
                EncryptionSpec.deterministic());
        byte[] ciphertext = new byte[16];
        assertDoesNotThrow(() -> CiphertextValidator.validate(field, ciphertext));
    }

    @Test
    void deterministic_acceptsLargerThan16Bytes() {
        FieldDefinition field = new FieldDefinition("email", FieldType.string(),
                EncryptionSpec.deterministic());
        byte[] ciphertext = new byte[64];
        assertDoesNotThrow(() -> CiphertextValidator.validate(field, ciphertext));
    }

    @Test
    void deterministic_rejectsLessThan16Bytes() {
        FieldDefinition field = new FieldDefinition("email", FieldType.string(),
                EncryptionSpec.deterministic());
        byte[] ciphertext = new byte[15];
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, ciphertext));
        assertTrue(ex.getMessage().contains("email"), "error should include field name");
        assertTrue(ex.getMessage().contains("16"), "error should include expected constraint");
    }

    // ── AES-GCM (Opaque): accept >= 28 bytes ───────────────────────────────

    @Test
    void opaque_accepts28Bytes() {
        FieldDefinition field = new FieldDefinition("secret", FieldType.string(),
                EncryptionSpec.opaque());
        byte[] ciphertext = new byte[28];
        assertDoesNotThrow(() -> CiphertextValidator.validate(field, ciphertext));
    }

    @Test
    void opaque_acceptsLargerThan28Bytes() {
        FieldDefinition field = new FieldDefinition("secret", FieldType.string(),
                EncryptionSpec.opaque());
        byte[] ciphertext = new byte[100];
        assertDoesNotThrow(() -> CiphertextValidator.validate(field, ciphertext));
    }

    @Test
    void opaque_rejectsLessThan28Bytes() {
        FieldDefinition field = new FieldDefinition("secret", FieldType.string(),
                EncryptionSpec.opaque());
        byte[] ciphertext = new byte[27];
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, ciphertext));
        assertTrue(ex.getMessage().contains("secret"), "error should include field name");
        assertTrue(ex.getMessage().contains("28"), "error should include expected constraint");
    }

    // ── OPE (OrderPreserving): accept exactly 8 bytes ───────────────────────

    @Test
    void orderPreserving_accepts8Bytes() {
        FieldDefinition field = new FieldDefinition("rank", FieldType.int32(),
                EncryptionSpec.orderPreserving());
        byte[] ciphertext = new byte[8];
        assertDoesNotThrow(() -> CiphertextValidator.validate(field, ciphertext));
    }

    @Test
    void orderPreserving_rejectsNot8Bytes() {
        FieldDefinition field = new FieldDefinition("rank", FieldType.int32(),
                EncryptionSpec.orderPreserving());
        byte[] ciphertext = new byte[7];
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, ciphertext));
        assertTrue(ex.getMessage().contains("rank"), "error should include field name");
        assertTrue(ex.getMessage().contains("8"), "error should include expected constraint");
    }

    @Test
    void orderPreserving_rejects9Bytes() {
        FieldDefinition field = new FieldDefinition("rank", FieldType.int32(),
                EncryptionSpec.orderPreserving());
        byte[] ciphertext = new byte[9];
        assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, ciphertext));
    }

    // ── DCPE (DistancePreserving): dimensions * 4 bytes ─────────────────────

    @Test
    void distancePreserving_acceptsCorrectLength() {
        int dimensions = 128;
        FieldDefinition field = new FieldDefinition("embedding",
                FieldType.vector(FieldType.Primitive.FLOAT32, dimensions),
                EncryptionSpec.distancePreserving());
        byte[] ciphertext = new byte[dimensions * 4]; // 512 bytes
        assertDoesNotThrow(() -> CiphertextValidator.validate(field, ciphertext));
    }

    @Test
    void distancePreserving_rejectsWrongLength() {
        int dimensions = 128;
        FieldDefinition field = new FieldDefinition("embedding",
                FieldType.vector(FieldType.Primitive.FLOAT32, dimensions),
                EncryptionSpec.distancePreserving());
        byte[] ciphertext = new byte[dimensions * 4 + 1];
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, ciphertext));
        assertTrue(ex.getMessage().contains("embedding"), "error should include field name");
    }

    // ── None: throws if called ──────────────────────────────────────────────

    @Test
    void none_throwsIfCalled() {
        FieldDefinition field = new FieldDefinition("plain", FieldType.string());
        byte[] ciphertext = new byte[32];
        assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, ciphertext));
    }

    // ── Null ciphertext → NullPointerException ──────────────────────────────

    @Test
    void nullCiphertext_throwsNpe() {
        FieldDefinition field = new FieldDefinition("email", FieldType.string(),
                EncryptionSpec.deterministic());
        assertThrows(NullPointerException.class,
                () -> CiphertextValidator.validate(field, null));
    }

    // ── Null field → NullPointerException ───────────────────────────────────

    @Test
    void nullField_throwsNpe() {
        assertThrows(NullPointerException.class,
                () -> CiphertextValidator.validate(null, new byte[16]));
    }

    // ── Empty ciphertext → IllegalArgumentException ─────────────────────────

    @Test
    void emptyCiphertext_throwsIae() {
        FieldDefinition field = new FieldDefinition("email", FieldType.string(),
                EncryptionSpec.deterministic());
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> CiphertextValidator.validate(field, new byte[0]));
        assertTrue(ex.getMessage().contains("email"), "error should include field name");
    }
}

package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import jlsm.encryption.EncryptionSpec;
import org.junit.jupiter.api.Test;

class JlsmDocumentPreEncryptedTest {

    // ── isPreEncrypted flag ────────────────────────────────────────────────

    @Test
    void of_returnsPreEncryptedFalse() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string())
                .build();
        JlsmDocument doc = JlsmDocument.of(schema, "name", "Alice");
        assertFalse(doc.isPreEncrypted());
    }

    @Test
    void preEncrypted_returnsPreEncryptedTrue() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string(), EncryptionSpec.deterministic())
                .build();
        // Pre-encrypted factory accepts byte[] for encrypted fields
        byte[] ciphertext = new byte[32]; // valid AES-SIV ciphertext (>= 16 bytes)
        JlsmDocument doc = JlsmDocument.preEncrypted(schema, "name", ciphertext);
        assertTrue(doc.isPreEncrypted());
    }

    // ── Pre-encrypted factory accepts byte[] for encrypted fields ───────

    @Test
    void preEncrypted_acceptsByteArrayForEncryptedField() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("secret", FieldType.string(), EncryptionSpec.opaque())
                .build();
        byte[] ciphertext = new byte[64];
        assertDoesNotThrow(() -> JlsmDocument.preEncrypted(schema, "secret", ciphertext));
    }

    // ── Pre-encrypted factory validates unencrypted fields normally ──────

    @Test
    void preEncrypted_validatesUnencryptedFieldsNormally() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string()) // no encryption — EncryptionSpec.NONE
                .field("secret", FieldType.string(), EncryptionSpec.deterministic())
                .build();
        byte[] ciphertext = new byte[32];
        // name = "Alice" should be type-validated normally
        assertDoesNotThrow(
                () -> JlsmDocument.preEncrypted(schema, "name", "Alice", "secret", ciphertext));
    }

    @Test
    void preEncrypted_wrongTypeForUnencryptedField_throws() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("age", FieldType.int32()) // no encryption
                .field("secret", FieldType.string(), EncryptionSpec.deterministic())
                .build();
        byte[] ciphertext = new byte[32];
        // age = "not-an-int" should fail type validation
        assertThrows(IllegalArgumentException.class,
                () -> JlsmDocument.preEncrypted(schema, "age", "not-an-int", "secret", ciphertext));
    }

    // ── Mixed schema: encrypted fields get byte[], unencrypted get normal ─

    @Test
    void preEncrypted_mixedSchema() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string()) // plaintext
                .field("email", FieldType.string(), EncryptionSpec.deterministic()) // encrypted
                .field("age", FieldType.int32()) // plaintext
                .build();
        byte[] ciphertext = new byte[32];
        JlsmDocument doc = JlsmDocument.preEncrypted(schema,
                "name", "Alice",
                "email", ciphertext,
                "age", 30);
        assertTrue(doc.isPreEncrypted());
    }

    // ── Null values still allowed for encrypted fields ──────────────────

    @Test
    void preEncrypted_nullValueForEncryptedField() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("secret", FieldType.string(), EncryptionSpec.deterministic())
                .build();
        // null is always accepted (absent field)
        assertDoesNotThrow(() -> JlsmDocument.preEncrypted(schema, "secret", null));
    }

    // ── Odd nameValuePairs length → IllegalArgumentException ────────────

    @Test
    void preEncrypted_oddNameValuePairsLength_throws() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string())
                .build();
        assertThrows(IllegalArgumentException.class,
                () -> JlsmDocument.preEncrypted(schema, "name"));
    }

    // ── Unknown field name → IllegalArgumentException ───────────────────

    @Test
    void preEncrypted_unknownFieldName_throws() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string())
                .build();
        assertThrows(IllegalArgumentException.class,
                () -> JlsmDocument.preEncrypted(schema, "unknown", "value"));
    }

    // ── Null schema → NullPointerException ──────────────────────────────

    @Test
    void preEncrypted_nullSchema_throws() {
        assertThrows(NullPointerException.class,
                () -> JlsmDocument.preEncrypted(null, "name", "value"));
    }
}

package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import java.lang.foreign.MemorySegment;
import java.util.Arrays;

import jlsm.core.io.MemorySerializer;
import jlsm.encryption.AesSivEncryptor;
import jlsm.encryption.EncryptionKeyHolder;
import jlsm.encryption.EncryptionSpec;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class DocumentSerializerPreEncryptedTest {

    private EncryptionKeyHolder keyHolder64;

    @BeforeEach
    void setUp() {
        byte[] key64 = new byte[64];
        Arrays.fill(key64, (byte) 0xAB);
        keyHolder64 = EncryptionKeyHolder.of(key64);
    }

    @AfterEach
    void tearDown() {
        if (keyHolder64 != null) {
            keyHolder64.close();
        }
    }

    // ── Pre-encrypted round-trip: valid ciphertext → correct plaintext ──

    @Test
    void preEncrypted_roundTrip_deterministicField() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string(), EncryptionSpec.deterministic())
                .field("age", FieldType.int32())
                .build();

        // First, encrypt "Alice" using the same mechanism the serializer would use
        byte[] key64Copy = keyHolder64.getKeyBytes();
        byte[] sivKey = new byte[64];
        System.arraycopy(key64Copy, 0, sivKey, 0, 32);
        System.arraycopy(key64Copy, 0, sivKey, 32, 32);
        Arrays.fill(key64Copy, (byte) 0);
        EncryptionKeyHolder sivKeyHolder = EncryptionKeyHolder.of(sivKey);
        AesSivEncryptor siv = new AesSivEncryptor(sivKeyHolder);

        // Serialize "Alice" to bytes the same way DocumentSerializer does
        byte[] plainBytes = "Alice".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        // The serializer serializes the field value (varint length + UTF-8 bytes)
        byte[] serializedPlain = new byte[1 + plainBytes.length]; // varint(5) = 1 byte
        serializedPlain[0] = (byte) plainBytes.length;
        System.arraycopy(plainBytes, 0, serializedPlain, 1, plainBytes.length);
        byte[] associatedData = "name".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        byte[] ciphertext = siv.encrypt(serializedPlain, associatedData);

        sivKeyHolder.close();

        // Create pre-encrypted document
        JlsmDocument doc = JlsmDocument.preEncrypted(schema, "name", ciphertext, "age", 30);

        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
        MemorySegment bytes = ser.serialize(doc);
        JlsmDocument out = ser.deserialize(bytes);

        assertEquals("Alice", out.getString("name"));
        assertEquals(30, out.getInt("age"));
    }

    // ── Pre-encrypted with invalid ciphertext length → throws ───────────

    @Test
    void preEncrypted_invalidCiphertextLength_throws() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("secret", FieldType.string(), EncryptionSpec.deterministic())
                .build();

        // AES-SIV requires >= 16 bytes; provide only 5
        byte[] tooShort = new byte[5];
        JlsmDocument doc = JlsmDocument.preEncrypted(schema, "secret", tooShort);

        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
        assertThrows(IllegalArgumentException.class, () -> ser.serialize(doc));
    }

    // ── Pre-encrypted with null ciphertext on encrypted field → throws ──

    @Test
    void preEncrypted_nullCiphertextOnEncryptedField_roundTripsAsNull() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("secret", FieldType.string(), EncryptionSpec.deterministic())
                .build();

        // null is always allowed — means the field is absent
        JlsmDocument doc = JlsmDocument.preEncrypted(schema, "secret", null);

        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
        MemorySegment bytes = ser.serialize(doc);
        JlsmDocument out = ser.deserialize(bytes);
        assertTrue(out.isNull("secret"));
    }

    // ── Mixed: encrypted fields pass through, unencrypted encode normally ─

    @Test
    void preEncrypted_mixedSchema_encryptedPassThroughUnencryptedNormal() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string()) // unencrypted
                .field("email", FieldType.string(), EncryptionSpec.deterministic()) // encrypted
                .field("age", FieldType.int32()) // unencrypted
                .build();

        // Encrypt "user@example.com" for the email field
        byte[] key64Copy = keyHolder64.getKeyBytes();
        byte[] sivKey = new byte[64];
        System.arraycopy(key64Copy, 0, sivKey, 0, 32);
        System.arraycopy(key64Copy, 0, sivKey, 32, 32);
        Arrays.fill(key64Copy, (byte) 0);
        EncryptionKeyHolder sivKeyHolder = EncryptionKeyHolder.of(sivKey);
        AesSivEncryptor siv = new AesSivEncryptor(sivKeyHolder);

        byte[] plainBytes = "user@example.com".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        byte[] serializedPlain = new byte[1 + plainBytes.length];
        serializedPlain[0] = (byte) plainBytes.length;
        System.arraycopy(plainBytes, 0, serializedPlain, 1, plainBytes.length);
        byte[] associatedData = "email".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        byte[] ciphertext = siv.encrypt(serializedPlain, associatedData);

        sivKeyHolder.close();

        JlsmDocument doc = JlsmDocument.preEncrypted(schema,
                "name", "Alice",
                "email", ciphertext,
                "age", 25);

        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
        MemorySegment bytes = ser.serialize(doc);
        JlsmDocument out = ser.deserialize(bytes);

        assertEquals("Alice", out.getString("name"));
        assertEquals("user@example.com", out.getString("email"));
        assertEquals(25, out.getInt("age"));
    }

    // ── Non-pre-encrypted document still encrypts on write ──────────────

    @Test
    void nonPreEncrypted_stillEncryptsOnWrite() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("name", FieldType.string(), EncryptionSpec.deterministic())
                .field("age", FieldType.int32())
                .build();

        JlsmDocument doc = JlsmDocument.of(schema, "name", "Alice", "age", 30);
        assertFalse(doc.isPreEncrypted());

        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
        MemorySegment bytes = ser.serialize(doc);
        JlsmDocument out = ser.deserialize(bytes);

        assertEquals("Alice", out.getString("name"));
        assertEquals(30, out.getInt("age"));
    }

    // ── Opaque (AES-GCM) pre-encrypted round-trip ───────────────────────

    @Test
    void preEncrypted_roundTrip_opaqueField() {
        JlsmSchema schema = JlsmSchema.builder("test", 1)
                .field("secret", FieldType.string(), EncryptionSpec.opaque())
                .build();

        // Create a key holder for GCM (32 bytes)
        byte[] key64Copy = keyHolder64.getKeyBytes();
        byte[] gcmKey = Arrays.copyOfRange(key64Copy, 0, 32);
        Arrays.fill(key64Copy, (byte) 0);
        EncryptionKeyHolder gcmKeyHolder = EncryptionKeyHolder.of(gcmKey);
        jlsm.encryption.AesGcmEncryptor gcm = new jlsm.encryption.AesGcmEncryptor(gcmKeyHolder);

        byte[] plainBytes = "top-secret".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        byte[] serializedPlain = new byte[1 + plainBytes.length];
        serializedPlain[0] = (byte) plainBytes.length;
        System.arraycopy(plainBytes, 0, serializedPlain, 1, plainBytes.length);
        byte[] ciphertext = gcm.encrypt(serializedPlain);

        gcmKeyHolder.close();

        JlsmDocument doc = JlsmDocument.preEncrypted(schema, "secret", ciphertext);

        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema, keyHolder64);
        MemorySegment bytes = ser.serialize(doc);
        JlsmDocument out = ser.deserialize(bytes);

        assertEquals("top-secret", out.getString("secret"));
    }
